-- Idempotent Seed Script for WorksAI Hub (`worksai_hub` schema)
DO $$ BEGIN
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, is_demo = EXCLUDED.is_demo;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, default_tenant_id = EXCLUDED.default_tenant_id;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET github_commit_sha = EXCLUDED.github_commit_sha, app_url = EXCLUDED.app_url;
END $$;
