  ('worksai-01', 'worksai-canvasarch', 'WorksAi CanvasArch', 'A. Web apps', 'web-apps', 'Turn plain-English system specs and schemas into editable hand-drawn architecture diagrams.', 'Replaces Miro subscription with a local-first MIT architecture whiteboard.', 'Excalidraw', 'https://github.com/excalidraw/excalidraw', '7ded689', 'MIT', 'https://github.com/DevinAiUk/worksai-canvasarch', 'afd569ff42fd7d07de7635e2dfb6bf76f555b8fe', '431bd9480b26799076db2ea09d2ec641f59329e9', 'canvasarch.worksai.org', 'https://canvasarch.worksai.org', 'https://devinai.uk/worksai/products/worksai-canvasarch/'),
  ('worksai-02', 'worksai-ledgerflow', 'WorksAi LedgerFlow', 'A. Web apps', 'web-apps', 'Local-first zero-based envelope budgeting with universal bank CSV normalization and 90-day runway forecasting.', 'Replaces YNAB with a local-first MIT envelope budgeter.', 'Actual Budget', 'https://github.com/actualbudget/actual', '92865f3', 'MIT', 'https://github.com/DevinAiUk/worksai-ledgerflow', '4b04d0bfc54661efa7aaf01168d1fef21a061b03', '65204e00460115435d3509883a440e0f7dd09625', 'ledgerflow.worksai.org', 'https://ledgerflow.worksai.org', 'https://devinai.uk/worksai/products/worksai-ledgerflow/'),
  ('worksai-03', 'worksai-wavecut-studio', 'WorksAi WaveCut Studio', 'A. Web apps', 'web-apps', 'Zero-backend browser waveform audio editor with automatic dead-air silence cutting and chapter show-notes generation.', 'Instant browser audio trimming and RMS silence removal.', 'AudioMass', 'https://github.com/pkalogiros/AudioMass', '21f5ee1', 'MIT', 'https://github.com/DevinAiUk/worksai-wavecut-studio', 'e509b8e4f60fb447353fbf5c8833fd919abd81fd', '2c18cc6f37119279cab712ff929180c3f1fc2207', 'wavecut.worksai.org', 'https://wavecut.worksai.org', 'https://devinai.uk/worksai/products/worksai-wavecut-studio/'),
  ('worksai-04', 'worksai-growthpulse', 'WorksAi GrowthPulse', 'B. SaaS products', 'saas-products', 'Cookie-free, GDPR-friendly web and funnel analytics SaaS with automated conversion drop-off diagnostics.', 'MIT multi-tenant privacy-first funnel analytics.', 'Umami', 'https://github.com/umami-software/umami', '559e3c6', 'MIT', 'https://github.com/DevinAiUk/worksai-growthpulse', '5e9203e3c45544477180d7a727830883b4275be1', '5e4b4ca1254cced25c0543693b440d62b8a6336c', 'growthpulse.worksai.org', 'https://growthpulse.worksai.org', 'https://devinai.uk/worksai/products/worksai-growthpulse/'),
  ('worksai-05', 'worksai-apisync-studio', 'WorksAi APISync Studio', 'B. SaaS products', 'saas-products', 'Collaborative API testing workspace that detects OpenAPI schema drift and auto-heals test assertions.', 'OpenAPI 3.x contract drift detection and assertion synthesis.', 'Hoppscotch', 'https://github.com/hoppscotch/hoppscotch', '55908a7', 'MIT', 'https://github.com/DevinAiUk/worksai-apisync-studio', '5655d81b3bf55bfd53f4ff486e9eb0e4beddeb8d', '9296c4f9d5dc75dd169ebb259febec32198a4693', 'apisync.worksai.org', 'https://apisync.worksai.org', 'https://devinai.uk/worksai/products/worksai-apisync-studio/'),
  ('worksai-06', 'worksai-omnidesk', 'WorksAi OmniDesk', 'B. SaaS products', 'saas-products', '100% MIT-clean omnichannel support inbox with BYOK RAG reply drafting and urgency triage.', 'MIT shared support inbox with SLA urgency routing and RAG reply drafting.', 'Chatwoot (MIT Community Core)', 'https://github.com/chatwoot/chatwoot', '515f9e0', 'MIT', 'https://github.com/DevinAiUk/worksai-omnidesk', 'b7c57d44df25473f0ca48ca20b20cadc483f5e59', 'c7af5bc7ba3a91a46717b30b058d6b3163f71a39', 'omnidesk.worksai.org', 'https://omnidesk.worksai.org', 'https://devinai.uk/worksai/products/worksai-omnidesk/'),
  ('worksai-07', 'worksai-graphmind', 'WorksAi GraphMind', 'C. Plugins or extensions', 'plugins-extensions', 'Bidirectional [[wikilink]] knowledge graphs, orphan link diagnostics, and MCP agent context for VS Code & Cursor.', 'MIT Markdown knowledge graph and MCP context tool.', 'Foam', 'https://github.com/foambubble/foam', '7a2e632', 'MIT', 'https://github.com/DevinAiUk/worksai-graphmind', '15390c3736a5e60c03e18275a9d4af0a243ea2f2', 'c23537abfd26d722629846a3a95487a70f650b42', 'graphmind.worksai.org', 'https://graphmind.worksai.org', 'https://devinai.uk/worksai/products/worksai-graphmind/'),
  ('worksai-08', 'worksai-clipguard', 'WorksAi ClipGuard', 'C. Plugins or extensions', 'plugins-extensions', 'Privacy-first clipboard history extension that scrubs API keys and PII before you paste into LLMs.', 'MIT secret and PII clipboard scrubber.', 'Maccy', 'https://github.com/p0deje/Maccy', 'f0b571e', 'MIT', 'https://github.com/DevinAiUk/worksai-clipguard', '1fdeefbda9195d49423b22b3acc8e880e58dd0ad', '4b6aded2c076e4e26babe594bf8e065eabaa7a37', 'clipguard.worksai.org', 'https://clipguard.worksai.org', 'https://devinai.uk/worksai/products/worksai-clipguard/'),
  ('worksai-09', 'worksai-commandbar', 'WorksAi CommandBar', 'C. Plugins or extensions', 'plugins-extensions', 'Cross-platform keystroke launcher and extensible plugin runner for Windows, macOS, Linux, and the browser.', 'MIT cross-platform command launcher and macro engine.', 'Ueli', 'https://github.com/oliverschwendener/ueli', '9b54c3d', 'MIT', 'https://github.com/DevinAiUk/worksai-commandbar', '276773f9bc56f4b353ce049480ecdd3dd018ef95', '3534c7e02a1904a956a3022ef884fbb8eb049658', 'commandbar.worksai.org', 'https://commandbar.worksai.org', 'https://devinai.uk/worksai/products/worksai-commandbar/'),
  ('worksai-10', 'worksai-linkengine', 'WorksAi LinkEngine', 'D. WordPress/PHP products', 'wordpress-php', 'MIT-licensed PHP URL shortener, UTM campaign builder, and WordPress bridge with link-rot detection.', 'MIT PHP short-link router and UTM builder.', 'Shlink', 'https://github.com/shlinkio/shlink', '9008811', 'MIT', 'https://github.com/DevinAiUk/worksai-linkengine', '17b34433ad632d8e814c3e2b0664b52a7fe89794', '99f73916aa60e811031127a762aad875aa04a455', 'linkengine.worksai.org', 'https://linkengine.worksai.org', 'https://devinai.uk/worksai/products/worksai-linkengine/'),
  ('worksai-11', 'worksai-commercecatalog', 'WorksAi CommerceCatalog', 'D. WordPress/PHP products', 'wordpress-php', 'MIT-licensed PHP headless e-commerce catalog with AI SKU enrichment and Schema.org Product JSON-LD.', 'MIT PHP headless catalog and JSON-LD generator.', 'Bagisto', 'https://github.com/bagisto/bagisto', '575e33b', 'MIT', 'https://github.com/DevinAiUk/worksai-commercecatalog', '58a2e65c4f739b6bef1d85ae4effd47ee9535223', '16b73cfbc5bb8b150a0b657960fbddd65275710e', 'commercecatalog.worksai.org', 'https://commercecatalog.worksai.org', 'https://devinai.uk/worksai/products/worksai-commercecatalog/'),
  ('worksai-12', 'worksai-forumpulse', 'WorksAi ForumPulse', 'D. WordPress/PHP products', 'wordpress-php', 'MIT-licensed PHP community forum with automated spam/toxicity scoring and thread-to-FAQ extraction.', 'MIT PHP discussion forum and FAQPage JSON-LD generator.', 'Flarum', 'https://github.com/flarum/framework', 'a1dd57e', 'MIT', 'https://github.com/DevinAiUk/worksai-forumpulse', '68c1cbfdf344e687f1d5d38c84bc4b7f1dc263c7', 'a83e3a2a3142516597afed5939b21fe4b5fb8a3c', 'forumpulse.worksai.org', 'https://forumpulse.worksai.org', 'https://devinai.uk/worksai/products/worksai-forumpulse/')
